 static int count,fail;static BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 static void Check(bool ok,string name){count++;if(!ok)fail++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static void Pump(int ms){DateTime until=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<until){Application.DoEvents();Thread.Sleep(5);}}
 static bool Finish(Task t,int ms=5000){DateTime until=DateTime.UtcNow.AddMilliseconds(ms);while(!t.IsCompleted&&DateTime.UtcNow<until)Pump(5);return t.Status==TaskStatus.RanToCompletion;}
 static object Field(object obj,string name){return obj.GetType().GetField(name,F).GetValue(obj);}
 static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(Control nested in All(c))yield return nested;}}
 static string Texts(Control root){return string.Join("\n",All(root).Select(c=>c.Text));}
 static void Shot(Control form,string path){if(Environment.GetEnvironmentVariable("WB_SKIP_SCREENSHOTS")=="1")return;Pump(100);using(var b=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(b,new Rectangle(Point.Empty,form.Size));b.Save(path);}}

 static string AccountTexts(WbPoolBoard board){int previous=board.PageIndex;var values=new List<string>();for(int i=0;i<board.PageCount;i++){board.NavigateAccount(i);Pump(5);values.Add(Texts(board));foreach(var section in All(board).OfType<WbSectionPager>())values.Add(section.FullText);}board.NavigateAccount(previous);return string.Join("\n",values);}
 static int AccountActionCount(WbPoolBoard board,string action){int previous=board.PageIndex,count=0;for(int i=0;i<board.PageCount;i++){board.NavigateAccount(i);var card=All(board).OfType<WbAccountCard>().Single();if(All(card).OfType<Button>().Any(b=>b.Text==action)||card.SecondaryActions.Contains(action))count++;}board.NavigateAccount(previous);return count;}
